INSERT INTO products (code, name, category, price, unit, updated_at) VALUES ('TP-002', 'Bò sốt cà chua', 'Món chính', 75000, 'phần', now()), ('TP-003', 'Súp cà chua', 'Món chính', 45000, 'phần', now()) ON CONFLICT (code) DO NOTHING;
INSERT INTO boms (code, product_code, version, output_quantity) VALUES ('BOM-002', 'TP-002', 1, 1), ('BOM-003', 'TP-003', 1, 1) ON CONFLICT (code) DO NOTHING;
INSERT INTO bom_details (bom_id, material_id, unit_id, quantity) SELECT b.id,m.id,m.unit_id,v.quantity FROM (VALUES ('BOM-002','TEST-NVL001',0.2::numeric),('BOM-002','DEMO-NVL02',0.1::numeric),('BOM-002','DEMO-NVL03',0.05::numeric),('BOM-003','DEMO-NVL02',0.2::numeric),('BOM-003','DEMO-NVL03',0.05::numeric)) AS v(bom_code,material_code,quantity) JOIN boms b ON b.code=v.bom_code JOIN materials m ON m.code=v.material_code ON CONFLICT (bom_id, material_id) DO NOTHING;
INSERT INTO production_orders (code,bom_id,branch_id,production_mode,quantity,status,material_status,assigned_employee_code,note) SELECT v.code,b.id,br.id,'MAKE_TO_STOCK',v.quantity,'PENDING','ISSUED','DEMO-KITCHEN','Dữ liệu mẫu: nguyên liệu cấp giả lập' FROM (VALUES ('LSX-005','BOM-002',5::numeric),('LSX-006','BOM-003',4::numeric)) AS v(code,bom_code,quantity) JOIN boms b ON b.code=v.bom_code CROSS JOIN branches br WHERE br.code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
INSERT INTO production_orders (code,bom_id,branch_id,production_mode,quantity,status,material_status,assigned_employee_code,note) SELECT 'LSX-007',b.id,br.id,'MAKE_TO_STOCK',3,'PENDING','UNCHECKED','DEMO-KITCHEN','Dữ liệu mẫu: chưa được cấp nguyên liệu' FROM boms b CROSS JOIN branches br WHERE b.code='BOM-002' AND br.code='TEST-CN01' ON CONFLICT (code) DO NOTHING;
